error_handling.syntax:
except Exception as e:
    if Err.<flag>:
        error = "<MESSAGE>"
    elif Err.<flag2>:
        error = "<MESSAGE2>"
    else:
        error = str(e) or "Unknown error"

single_exit_point.syntax:
# Cleanup and return - single exit point
if retv:
    output.update(result)
else:
    output["error"] = error

return retv

